-- Bulk-inserts the 448 cutting dies (Dados de corte) shared by the user,
-- as products under the DADOS_CORTE material type, with their technical
-- attribute values. SPECIAL CLIENT maps to products.owner_customer_id
-- (joined against the customers already seeded by legal_name); GENERIC
-- or blank means no owner (shared/generic tooling).
--
-- Assumes a single organization; adjust the org subquery if there is more
-- than one.

-- Ensure the one die_type option not seeded earlier exists.
with org as (
  select id from pomgt.organizations order by created_at limit 1
),
mt as (
  select id from pomgt.material_types where organization_id = (select id from org) and code = 'DADOS_CORTE'
)
insert into pomgt.material_attribute_options (organization_id, attribute_definition_id, option_value, option_label, sort_order, is_active)
select (select id from org), ad.id, 'flexible_drill', 'Flexible drill', 50, true
from pomgt.material_attribute_definitions ad
where ad.material_type_id = (select id from mt) and ad.attribute_key = 'die_type'
  and not exists (
    select 1 from pomgt.material_attribute_options o
    where o.attribute_definition_id = ad.id and o.option_value = 'flexible_drill'
  );

-- Ensure a 'Pieza' unit exists for base_uom_id (dies are discrete tools).
insert into pomgt.uom_categories (organization_id, code, name, description)
select (select id from pomgt.organizations order by created_at limit 1), 'CANTIDAD', 'Cantidad', 'Unidades discretas, por ejemplo piezas o rollos.'
where not exists (
  select 1 from pomgt.uom_categories
  where organization_id = (select id from pomgt.organizations order by created_at limit 1) and code = 'CANTIDAD'
);

insert into pomgt.units_of_measure (organization_id, category_id, code, name, symbol, is_base_unit, is_active)
select (select id from pomgt.organizations order by created_at limit 1),
       (select id from pomgt.uom_categories where organization_id = (select id from pomgt.organizations order by created_at limit 1) and code = 'CANTIDAD'),
       'PZA', 'Pieza', 'pza', true, true
where not exists (
  select 1 from pomgt.units_of_measure
  where organization_id = (select id from pomgt.organizations order by created_at limit 1) and code = 'PZA'
);

-- Ensure a 'Herramental' product type exists for tooling.
insert into pomgt.product_types (organization_id, code, name, system_class, is_active)
select (select id from pomgt.organizations order by created_at limit 1), 'TOOLING', 'Herramental', 'tooling', true
where not exists (
  select 1 from pomgt.product_types
  where organization_id = (select id from pomgt.organizations order by created_at limit 1) and code = 'TOOLING'
);

with org as (
  select id from pomgt.organizations order by created_at limit 1
),
mt as (
  select id from pomgt.material_types where organization_id = (select id from org) and code = 'DADOS_CORTE'
),
pt as (
  select id from pomgt.product_types where organization_id = (select id from org) and code = 'TOOLING'
),
uom as (
  select id from pomgt.units_of_measure where organization_id = (select id from org) and code = 'PZA'
),
cust as (
  select id, legal_name from pomgt.customers where organization_id = (select id from org)
)
insert into pomgt.products (
  organization_id, sku, name, material_type_id, product_type_catalog_id, product_type,
  base_uom_id, owner_customer_id, is_manufacturable, is_purchasable, is_sellable,
  is_customer_specific, track_lots, is_active
)
select (select id from org), v.sku, v.name, (select id from mt), (select id from pt), 'tooling',
       (select id from uom), cust.id, false, true, false, cust.id is not null, true, true
