  ('DIE-BL_448', 'roll_repeat', null, 6.375),
  ('DIE-BL_448', 'shape', 'square', null),
  ('DIE-BL_448', 'die_type', 'solid_die', null),
  ('DIE-BL_448', 'gap_ar', '0.137', null),
  ('DIE-BL_448', 'corner_radius', null, 0.015),
  ('DIE-BL_448', 'liner', '50', null),
  ('DIE-BL_448', 'internal_folio', 'BL_448', null),
  ('DIE-BL_448', 'given_folio', '328497', null),
  ('DIE-BL_448', 'dice_size', null, 7.0),
  ('DIE-BL_448', 'state', 'good', null),
  ('DIE-BL_448', 'location', 'RACA PROD.', null)
) as v(sku, attribute_key, value_text, value_number)
join pomgt.products p on p.sku = v.sku and p.organization_id = (select id from org)
join pomgt.product_revisions pr on pr.product_id = p.id and pr.revision_code = 'V.01'
join pomgt.material_attribute_definitions ad
  on ad.material_type_id = (select id from mt) and ad.attribute_key = v.attribute_key;

notify pgrst, 'reload schema';
